package de.mossgrabers.dbm.bitwig;

import com.bitwig.extension.api.PlatformType;
import com.bitwig.extension.controller.AutoDetectionMidiPortNamesList;
import com.bitwig.extension.controller.ControllerExtension;
import com.bitwig.extension.controller.ControllerExtensionDefinition;
import com.bitwig.extension.controller.api.ControllerHost;

import java.util.UUID;


/**
 * The definition of one controller of the Rust core. The subclasses are generated by
 * tools/gen_definitions.py from the core's controller list, since Bitwig finds definitions only
 * as classes listed in META-INF/services.
 */
public abstract class DbmExtensionDefinition extends ControllerExtensionDefinition
{
    private static final String VERSION     = "0.1.0";
    private static final int    API_VERSION = 21;

    private final UUID          id;
    private final String        coreId;
    private final String        vendor;
    private final String        model;
    private final int           numMidiInPorts;
    private final int           numMidiOutPorts;
    private final String [][][] windowsPorts;
    private final String [][][] linuxPorts;
    private final String [][][] macPorts;


    /**
     * Constructor.
     *
     * @param id The UUID of the extension (differs from the core's, so that the extension can be
     *            installed next to the Java DrivenByMoss)
     * @param coreId The UUID of the controller in the core
     * @param vendor The hardware vendor
     * @param model The hardware model
     * @param numMidiInPorts The number of MIDI inputs
     * @param numMidiOutPorts The number of MIDI outputs
     * @param windowsPorts The port names for the automatic detection on Windows: pairs of input
     *            names and output names
     * @param linuxPorts The port names for the automatic detection on Linux
     * @param macPorts The port names for the automatic detection on macOS
     */
    protected DbmExtensionDefinition (final String id, final String coreId, final String vendor, final String model, final int numMidiInPorts, final int numMidiOutPorts, final String [][][] windowsPorts, final String [][][] linuxPorts, final String [][][] macPorts)
    {
        this.id = UUID.fromString (id);
        this.coreId = coreId;
        this.vendor = vendor;
        this.model = model;
        this.numMidiInPorts = numMidiInPorts;
        this.numMidiOutPorts = numMidiOutPorts;
        this.windowsPorts = windowsPorts;
        this.linuxPorts = linuxPorts;
        this.macPorts = macPorts;
    }


    /**
     * Get the UUID of the controller in the core.
     *
     * @return The UUID
     */
    public String getCoreId ()
    {
        return this.coreId;
    }


    /** {@inheritDoc} */
    @Override
    public String getName ()
    {
        return this.model + " (Rust)";
    }


    /** {@inheritDoc} */
    @Override
    public String getAuthor ()
    {
        return "DrivenByMoss (Rust)";
    }


    /** {@inheritDoc} */
    @Override
    public String getVersion ()
    {
        return VERSION;
    }


    /** {@inheritDoc} */
    @Override
    public UUID getId ()
    {
        return this.id;
    }


    /** {@inheritDoc} */
    @Override
    public int getRequiredAPIVersion ()
    {
        return API_VERSION;
    }


    /** {@inheritDoc} */
    @Override
    public String getHardwareVendor ()
    {
        return this.vendor;
    }


    /** {@inheritDoc} */
    @Override
    public String getHardwareModel ()
    {
        return this.model + " (Rust)";
    }


    /** {@inheritDoc} */
    @Override
    public int getNumMidiInPorts ()
    {
        return this.numMidiInPorts;
    }


    /** {@inheritDoc} */
    @Override
    public int getNumMidiOutPorts ()
    {
        return this.numMidiOutPorts;
    }


    /** {@inheritDoc} */
    @Override
    public void listAutoDetectionMidiPortNames (final AutoDetectionMidiPortNamesList list, final PlatformType platformType)
    {
        final String [][][] pairs = switch (platformType)
        {
            case WINDOWS -> this.windowsPorts;
            case LINUX -> this.linuxPorts;
            case MAC -> this.macPorts;
        };
        for (final String [][] pair: pairs)
            list.add (pair[0], pair[1]);
    }


    /** {@inheritDoc} */
    @Override
    public ControllerExtension createInstance (final ControllerHost host)
    {
        return new DbmExtension (this, host);
    }
}
